<main class="container py-5"><div class="dashboard-head"><div><span class="eyebrow">COACH</span><h1 class="fw-bold">Séances</h1></div><a href="/coach" class="btn btn-outline-dark">Dashboard</a></div><form class="form-card row g-3 mb-5" method="post" action="/coach/seances/add"><input type="hidden" name="csrf" value="<?=csrf()?>"><div class="col-md-4"><label class="form-label">Activité</label><select name="activity_id" class="form-select"><?php foreach($activities as $a): ?><option value="<?=$a['id']?>"><?=e($a['title'])?></option><?php endforeach; ?></select></div><div class="col-md-4"><label class="form-label">Date et heure</label><input type="datetime-local" name="starts_at" class="form-control" required></div><div class="col-md-2"><label class="form-label">Durée</label><input type="number" name="duration_minutes" value="60" class="form-control" required></div><div class="col-md-2"><label class="form-label">Places</label><input type="number" name="capacity" value="12" class="form-control" required></div><div class="col-md-6"><input name="coach_name" class="form-control" placeholder="Nom du coach" required></div><div class="col-md-4"><input name="room" class="form-control" placeholder="Salle"></div><div class="col-md-2"><button class="btn btn-accent w-100">Ajouter</button></div></form><div class="table-responsive"><table class="table"><thead><tr><th>Date</th><th>Activité</th><th>Coach</th><th>Places</th><th></th></tr></thead><tbody><?php foreach($sessions as $s): ?><tr><td><?=date('d/m/Y H:i',strtotime($s['starts_at']))?></td><td><?=e($s['title'])?></td><td><?=e($s['coach_name'])?></td><td><?=$s['remaining']?> / <?=$s['capacity']?></td><td><form method="post" action="/coach/seances/delete" onsubmit="return confirm('Supprimer cette séance ?')"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$s['id']?>"><button class="btn btn-sm btn-outline-danger">Supprimer</button></form></td></tr><?php endforeach; ?></tbody></table></div></main>